/**
 * needs_you: pending cards (questions, plans, permissions, forms) stand for it, its folded children's included.
 */
@Serializable
data class ReasonCards(
    override val kind: String = "cards",
    /**
     * How many cards its row holds.
     */
    val n: Int = 0,
    /**
     * None of them is the owner's yet: questions the assistant is still deciding on (D11).
     */
    val held: Boolean? = null,
) : AgentReason

/**
 * needs_you: a dialog its terminal shows that no card stands for.
 */
@Serializable
data class ReasonTerminalDialog(
    override val kind: String = "terminal_dialog",
) : AgentReason

/**
 * working: its turn runs, or its task's supervisor holds every card it asked.
 */
@Serializable
data class ReasonTurn(
    override val kind: String = "turn",
) : AgentReason

/**
 * working: its turn ended and only its background work runs (#2935).
 */
@Serializable
data class ReasonBackground(
    override val kind: String = "background",
    /**
